<span class="line">            <span class="token keyword">if</span> <span class="token punctuation">(</span>bitmap<span class="token punctuation">[</span><span class="token number">0</span><span class="token punctuation">]</span> <span class="token operator">!=</span> <span class="token number">0</span><span class="token punctuation">)</span> <span class="token class-name">HFReleaseImageBitmap</span><span class="token punctuation">(</span>bitmap<span class="token punctuation">[</span><span class="token number">0</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
